var t=`1120-texas-beef-brisket`;var r=`world-1120`;var s=`US`;var n=`northern-america`;var a=4;var o=683;var d={en:`Texas Beef Brisket`,ua:`Техаський яловичий брискет`};var l={en:`Texas Beef Brisket is a dish from United States prepared with beef brisket, apple cider vinegar. This is a home-scale version with measured ingredients in the individual steps where they are used. Home slow-roasted brisket without a smoker; Texas smoked brisket requires smoke and temperature control.`,ua:`Техаський яловичий брискет, страва кухні країни Сполучені Штати Америки, яку готують із таких продуктів: яловича грудинка, яблучний оцет. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Домашній брискет повільно запікають без коптильні; техаський потребує диму й контролю температури.`};var u=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 180 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 180 хвилин.`,t:[`marinating`],m:180,i:[[`beef-brisket`,1800,`g`],[`table-salt`,18,`g`],[`ground-black-pepper`,20,`g`],[`smoked-paprika`,10,`g`]]},{en:`Roast the foil-covered brisket low and slow at about 115–125°C for 7–9 hours, until probe-tender (often around 92–96°C inside); rest well before slicing. Do not use 190°C.`,ua:`Повільно запікайте брискет під фольгою при близько 115–125°C протягом 7–9 годин до м’якості для щупа (часто близько 92–96°C усередині); добре витримайте перед нарізанням. Не запікайте при 190°C.`,t:[`low-and-slow-cooking`],m:450,i:[]},{en:`Let the cooked rice rest, covered, for about 50 minutes, then fluff and serve.`,ua:`Залиште готовий рис під кришкою на близько 50 хвилин, тоді розпушіть і подавайте.`,t:[`rice-resting`,`fluffing-grains`],m:50,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`apple-cider-vinegar`,35,`ml`]]}];var g={slug:t,id:r,country:`US`,region:n,servings:4,minutes:683,title:d,text:l,steps:u};export{s as country,g as default,r as id,o as minutes,n as region,a as servings,t as slug,u as steps,l as text,d as title};